const sel=document.querySelector('select');sel.value='50';sel.dispatchEvent(new Event('change',{bubbles:true}));
const next=[...document.querySelectorAll('button')].find(b=>b.textContent.trim()=='Next');
const m=new Map();
for(let i=0;i<30;i++){await new Promise(r=>setTimeout(r,150));
document.querySelectorAll('tbody tr').forEach(tr=>{const c=[...tr.children].map(x=>x.textContent.trim());m.set(c[0],c)});
if(next.disabled)break;next.click();}
const rows=[...m.values()];const f=rows.filter(c=>c[3]=='West'&&c[5]=='Refunded');
rows.length+' '+f.length+' '+f.reduce((s,c)=>s+parseFloat(c[6].replace(/[$,]/g,'')),0).toFixed(2)+' '+document.body.innerText.match(/Page \d+ of \d+/)

